// Stock CSV exports include all current locations and ignore the visible item filter.
function readCSV(text){let fields=[],line=[],value='',quoted=false;for(let i=text.startsWith('\uFEFF')?1:0;i<text.length;i++){const char=text[i];if(char==='"'){if(quoted&&text[i+1]==='"'){value+='"';i++;}else quoted=!quoted;}else if(char===';'&&!quoted){line.push(value);value='';}else if(char==='\r'&&text[i+1]==='\n'&&!quoted){line.push(value);fields.push(line);line=[];value='';i++;}else value+=char;}line.push(value);fields.push(line);return fields;}
